// AUTO-GENERATED from "Business Sale Service Agreement - V0.2.txt" (V0.2) by scripts/genSalesAgreementClauses.js.
// Verbatim clause text; do not hand-edit — re-run the generator to refresh.
module.exports = [
  ["PURPOSE", "<p style=\"margin:6px 0;\">This Agreement sets out the terms under which Seventh Sky will provide Business Sale Management Services to assist the Client in preparing, marketing, promoting and coordinating the sale of the Client's business.</p><p style=\"margin:6px 0;\">The specific services, pricing and project requirements for each engagement will be confirmed in the approved Quotation and Work Order.</p>"],
  ["TERM", "<p style=\"margin:6px 0;\">This Agreement becomes effective on the date it is signed by both Parties and continues until:</p><ul style=\"margin:4px 0 8px 18px;padding:0;list-style-type:disc;\"><li style=\"margin:2px 0;\">the agreed Services have been completed;</li><li style=\"margin:2px 0;\">all outstanding payments have been made; and</li><li style=\"margin:2px 0;\">all obligations under this Agreement have been fulfilled,</li></ul><p style=\"margin:6px 0;\">unless terminated earlier in accordance with this Agreement.</p><p style=\"margin:6px 0;\">Where ongoing sale management services are engaged, this Agreement continues for the period specified in the approved Work Order.</p>"],
  ["SERVICES", "<p style=\"margin:6px 0;\">The Client may request one or more of the following services.</p><p style=\"margin:6px 0;\">Only the services selected in Schedule A or the approved Work Order form part of this Agreement.</p><p style=\"margin:10px 0 4px;font-weight:700;color:#012a4e;\">Business Sale Consultation</p><ul style=\"margin:4px 0 8px 6px;padding:0;list-style:none;\"><li style=\"margin:2px 0;\">☐ Initial Consultation</li><li style=\"margin:2px 0;\">☐ Business Sale Strategy</li><li style=\"margin:2px 0;\">☐ Market Positioning Advice</li><li style=\"margin:2px 0;\">☐ Sale Planning</li><li style=\"margin:2px 0;\">☐ Business Readiness Assessment</li></ul><p style=\"margin:10px 0 4px;font-weight:700;color:#012a4e;\">Business Preparation</p><ul style=\"margin:4px 0 8px 6px;padding:0;list-style:none;\"><li style=\"margin:2px 0;\">☐ Business Presentation Assessment</li><li style=\"margin:2px 0;\">☐ Operational Review Coordination</li><li style=\"margin:2px 0;\">☐ Business Profile Preparation</li><li style=\"margin:2px 0;\">☐ Documentation Preparation Coordination</li><li style=\"margin:2px 0;\">☐ Photography &amp; Videography</li></ul><p style=\"margin:10px 0 4px;font-weight:700;color:#012a4e;\">Marketing &amp; Buyer Sourcing</p><ul style=\"margin:4px 0 8px 6px;padding:0;list-style:none;\"><li style=\"margin:2px 0;\">☐ Business Listing Preparation</li><li style=\"margin:2px 0;\">☐ Online Marketing</li><li style=\"margin:2px 0;\">☐ Social Media Promotion</li><li style=\"margin:2px 0;\">☐ Buyer Lead Generation</li><li style=\"margin:2px 0;\">☐ Investor Outreach</li><li style=\"margin:2px 0;\">☐ Buyer Enquiry Management</li></ul><p style=\"margin:10px 0 4px;font-weight:700;color:#012a4e;\">Buyer Screening &amp; Negotiation</p><ul style=\"margin:4px 0 8px 6px;padding:0;list-style:none;\"><li style=\"margin:2px 0;\">☐ Preliminary Buyer Screening</li><li style=\"margin:2px 0;\">☐ Financial Capability Review</li><li style=\"margin:2px 0;\">☐ Buyer Qualification</li><li style=\"margin:2px 0;\">☐ Offer Coordination</li><li style=\"margin:2px 0;\">☐ Sale Negotiation Coordination</li></ul><p style=\"margin:10px 0 4px;font-weight:700;color:#012a4e;\">Transaction Coordination</p><ul style=\"margin:4px 0 8px 6px;padding:0;list-style:none;\"><li style=\"margin:2px 0;\">☐ Due Diligence Coordination</li><li style=\"margin:2px 0;\">☐ Sale Documentation Coordination</li><li style=\"margin:2px 0;\">☐ Settlement Coordination</li><li style=\"margin:2px 0;\">☐ Business Handover Coordination</li><li style=\"margin:2px 0;\">☐ Post-Settlement Support</li></ul><p style=\"margin:10px 0 4px;font-weight:700;color:#012a4e;\">Additional Services</p><ul style=\"margin:4px 0 8px 6px;padding:0;list-style:none;\"><li style=\"margin:2px 0;\">☐ Business Valuation Coordination</li><li style=\"margin:2px 0;\">☐ Legal Documentation Coordination</li><li style=\"margin:2px 0;\">☐ Financial Adviser Coordination</li><li style=\"margin:2px 0;\">☐ Tax Adviser Coordination</li><li style=\"margin:2px 0;\">☐ Other</li></ul><p style=\"margin:6px 0;\">Additional services may be included by written agreement.</p>"],
  ["BUSINESS DETAILS", "<p style=\"margin:6px 0;\">The details of each engagement shall be recorded in Schedule B or the approved Work Order, including:</p><ul style=\"margin:4px 0 8px 18px;padding:0;list-style-type:disc;\"><li style=\"margin:2px 0;\">Business Name;</li><li style=\"margin:2px 0;\">Business Type;</li><li style=\"margin:2px 0;\">Business Address;</li><li style=\"margin:2px 0;\">Ownership Structure;</li><li style=\"margin:2px 0;\">Reason for Sale;</li><li style=\"margin:2px 0;\">Indicative Sale Price;</li><li style=\"margin:2px 0;\">Selected Services;</li><li style=\"margin:2px 0;\">Agreed Pricing;</li><li style=\"margin:2px 0;\">Project Timeline; and</li><li style=\"margin:2px 0;\">Special Requirements.</li></ul><p style=\"margin:6px 0;\">If any inconsistency exists between this Agreement and the Work Order, the Work Order prevails for that project only.</p>"],
  ["RESPONSIBILITIES OF SEVENTH SKY", "<p style=\"margin:6px 0;\">Seventh Sky will:</p><ul style=\"margin:4px 0 8px 18px;padding:0;list-style-type:disc;\"><li style=\"margin:2px 0;\">assess the Client's sale requirements;</li><li style=\"margin:2px 0;\">assist in preparing the business for sale;</li><li style=\"margin:2px 0;\">coordinate marketing activities;</li><li style=\"margin:2px 0;\">promote the business through appropriate marketing channels;</li><li style=\"margin:2px 0;\">coordinate buyer enquiries and inspections;</li><li style=\"margin:2px 0;\">undertake preliminary buyer screening where requested;</li><li style=\"margin:2px 0;\">coordinate negotiations where authorised;</li><li style=\"margin:2px 0;\">coordinate due diligence, documentation and settlement activities;</li><li style=\"margin:2px 0;\">provide regular progress updates; and</li><li style=\"margin:2px 0;\">use reasonable care and skill in delivering the agreed Services.</li></ul><p style=\"margin:6px 0;\">Unless otherwise agreed in writing, Seventh Sky acts as the Client's business sale consultant and transaction coordinator and is not the purchaser, legal adviser or financial adviser for the transaction.</p>"],
  ["CLIENT RESPONSIBILITIES", "<p style=\"margin:6px 0;\">The Client agrees to:</p><ul style=\"margin:4px 0 8px 18px;padding:0;list-style-type:disc;\"><li style=\"margin:2px 0;\">provide accurate and complete information regarding the business;</li><li style=\"margin:2px 0;\">provide all documents reasonably required for the sale process;</li><li style=\"margin:2px 0;\">ensure the business is lawfully operating;</li><li style=\"margin:2px 0;\">promptly advise Seventh Sky of any material changes affecting the business;</li><li style=\"margin:2px 0;\">cooperate with inspections and buyer meetings;</li><li style=\"margin:2px 0;\">review and approve marketing material before publication where required;</li><li style=\"margin:2px 0;\">obtain independent legal, taxation and financial advice where appropriate;</li><li style=\"margin:2px 0;\">pay all agreed fees in accordance with this Agreement; and</li><li style=\"margin:2px 0;\">cooperate throughout the sale process.</li></ul><p style=\"margin:6px 0;\">The Client remains responsible for the ownership, operation and legal compliance of the business and for the accuracy of all information provided to prospective buyers.</p>"],
  ["QUOTATIONS & WORK ORDERS", "<p style=\"margin:6px 0;\">Before work commences, Seventh Sky will provide a Quotation and, where applicable, a Work Order setting out:</p><ul style=\"margin:4px 0 8px 18px;padding:0;list-style-type:disc;\"><li style=\"margin:2px 0;\">selected services;</li><li style=\"margin:2px 0;\">scope of work;</li><li style=\"margin:2px 0;\">estimated project timeline;</li><li style=\"margin:2px 0;\">agreed fees;</li><li style=\"margin:2px 0;\">payment schedule;</li><li style=\"margin:2px 0;\">expected deliverables; and</li><li style=\"margin:2px 0;\">any special conditions.</li></ul><p style=\"margin:6px 0;\">Services will commence once the Client accepts the Quotation or Work Order.</p><p style=\"margin:6px 0;\">Where the Client requests additional services after acceptance, a revised quotation or approved variation may be issued.</p>"],
  ["SERVICE FEES & PAYMENT", "<p style=\"margin:6px 0;\">The total project cost will be specified in the approved Quotation or Work Order.</p><p style=\"margin:6px 0;\">Project fees may include:</p><ul style=\"margin:4px 0 8px 18px;padding:0;list-style-type:disc;\"><li style=\"margin:2px 0;\">consultation fees;</li><li style=\"margin:2px 0;\">business sale assessment;</li><li style=\"margin:2px 0;\">business preparation services;</li><li style=\"margin:2px 0;\">marketing and advertising;</li><li style=\"margin:2px 0;\">buyer sourcing and preliminary screening;</li><li style=\"margin:2px 0;\">inspection coordination;</li><li style=\"margin:2px 0;\">negotiation coordination;</li><li style=\"margin:2px 0;\">due diligence coordination;</li><li style=\"margin:2px 0;\">documentation coordination;</li><li style=\"margin:2px 0;\">settlement coordination;</li><li style=\"margin:2px 0;\">success fees (where applicable);</li><li style=\"margin:2px 0;\">approved third-party service fees (where applicable); and</li><li style=\"margin:2px 0;\">any approved additional services.</li></ul><p style=\"margin:6px 0;\">The Client agrees to pay all agreed fees in accordance with the approved payment schedule.</p><p style=\"margin:6px 0;\">Advertising costs, legal fees, accounting fees, valuation fees, government charges, taxes, stamp duty and other third-party costs are payable by the Client unless otherwise stated in the approved Quotation or Work Order.</p>"],
  ["PAYMENT TERMS", "<p style=\"margin:6px 0;\">Unless otherwise agreed in writing:</p><p style=\"margin:6px 0;\">Business Sale Services</p><ul style=\"margin:4px 0 8px 18px;padding:0;list-style-type:disc;\"><li style=\"margin:2px 0;\">Deposit upon acceptance of the Quotation or Work Order.</li></ul><p style=\"margin:6px 0;\">Progress payment (where applicable).</p><ul style=\"margin:4px 0 8px 18px;padding:0;list-style-type:disc;\"><li style=\"margin:2px 0;\">Final payment upon completion of the agreed Services or settlement of the business sale, whichever occurs first.</li></ul><p style=\"margin:6px 0;\">Ongoing Sale Management Services</p><p style=\"margin:6px 0;\">Where ongoing business sale management services are provided, payment may be made:</p><ul style=\"margin:4px 0 8px 6px;padding:0;list-style:none;\"><li style=\"margin:2px 0;\">☐ Weekly</li><li style=\"margin:2px 0;\">☐ Monthly</li><li style=\"margin:2px 0;\">☐ Quarterly</li><li style=\"margin:2px 0;\">☐ Annually</li></ul><p style=\"margin:6px 0;\">as specified in the approved Work Order.</p><p style=\"margin:6px 0;\">Invoices are payable within the period stated on the invoice.</p><p style=\"margin:6px 0;\">Late payments may result in suspension of the Services.</p>"],
  ["MARKETING, BUYER SOURCING & SALE COORDINATION", "<p style=\"margin:6px 0;\">Seventh Sky will use reasonable efforts to market the Client's business and identify suitable prospective buyers.</p><p style=\"margin:6px 0;\">The Client acknowledges that:</p><ul style=\"margin:4px 0 8px 18px;padding:0;list-style-type:disc;\"><li style=\"margin:2px 0;\">buyer availability is subject to market conditions;</li><li style=\"margin:2px 0;\">prospective buyers have the right to decide whether to proceed with a purchase;</li><li style=\"margin:2px 0;\">business values and market conditions may change;</li><li style=\"margin:2px 0;\">successful sale of the business cannot be guaranteed; and</li><li style=\"margin:2px 0;\">the final sale agreement remains subject to mutual acceptance between the Client and the purchaser.</li></ul><p style=\"margin:6px 0;\">Where requested, Seventh Sky may coordinate:</p><ul style=\"margin:4px 0 8px 18px;padding:0;list-style-type:disc;\"><li style=\"margin:2px 0;\">business marketing;</li><li style=\"margin:2px 0;\">buyer enquiries;</li><li style=\"margin:2px 0;\">inspections;</li><li style=\"margin:2px 0;\">preliminary buyer screening;</li><li style=\"margin:2px 0;\">offer management;</li><li style=\"margin:2px 0;\">sale negotiations;</li><li style=\"margin:2px 0;\">due diligence coordination;</li><li style=\"margin:2px 0;\">documentation;</li><li style=\"margin:2px 0;\">settlement coordination; and</li><li style=\"margin:2px 0;\">business handover.</li></ul>"],
  ["PROJECT TIMELINES", "<p style=\"margin:6px 0;\">Estimated commencement and completion dates will be provided in the approved Quotation or Work Order.</p><p style=\"margin:6px 0;\">Project timeframes may be affected by:</p><ul style=\"margin:4px 0 8px 18px;padding:0;list-style-type:disc;\"><li style=\"margin:2px 0;\">market demand;</li><li style=\"margin:2px 0;\">availability of suitable buyers;</li><li style=\"margin:2px 0;\">Client instructions;</li><li style=\"margin:2px 0;\">negotiations between the parties;</li><li style=\"margin:2px 0;\">due diligence processes;</li><li style=\"margin:2px 0;\">legal documentation;</li><li style=\"margin:2px 0;\">finance approval;</li><li style=\"margin:2px 0;\">regulatory requirements;</li><li style=\"margin:2px 0;\">public holidays; or</li><li style=\"margin:2px 0;\">other circumstances beyond Seventh Sky's reasonable control.</li></ul><p style=\"margin:6px 0;\">Where delays occur, Seventh Sky will keep the Client reasonably informed and provide an updated estimated timeframe where reasonably practicable.</p>"],
  ["VARIATIONS & ADDITIONAL SERVICES", "<p style=\"margin:6px 0;\">A variation occurs where the Client requests work outside the approved scope of Services or where additional work becomes necessary.</p><p style=\"margin:6px 0;\">Examples include:</p><ul style=\"margin:4px 0 8px 18px;padding:0;list-style-type:disc;\"><li style=\"margin:2px 0;\">additional marketing campaigns;</li><li style=\"margin:2px 0;\">revised sale strategy;</li><li style=\"margin:2px 0;\">additional buyer sourcing;</li><li style=\"margin:2px 0;\">multiple negotiation rounds;</li><li style=\"margin:2px 0;\">business valuation coordination;</li><li style=\"margin:2px 0;\">additional due diligence;</li><li style=\"margin:2px 0;\">legal or financial adviser coordination;</li><li style=\"margin:2px 0;\">settlement extensions; or</li><li style=\"margin:2px 0;\">any other Client-requested services.</li></ul><p style=\"margin:6px 0;\">Where practical, Seventh Sky will advise the Client of:</p><ul style=\"margin:4px 0 8px 18px;padding:0;list-style-type:disc;\"><li style=\"margin:2px 0;\">the additional work;</li><li style=\"margin:2px 0;\">any additional charges; and</li><li style=\"margin:2px 0;\">any expected impact on the project timeline.</li></ul><p style=\"margin:6px 0;\">No variation will proceed without the Client's approval unless immediate action is reasonably necessary to protect the Client's interests.</p>"],
  ["BUYER SCREENING & THIRD-PARTY SERVICES", "<p style=\"margin:6px 0;\">Where requested, Seventh Sky may undertake preliminary buyer screening using information voluntarily provided by prospective buyers.</p><p style=\"margin:6px 0;\">The Client acknowledges that:</p><ul style=\"margin:4px 0 8px 18px;padding:0;list-style-type:disc;\"><li style=\"margin:2px 0;\">preliminary screening is based on information reasonably available at the time;</li><li style=\"margin:2px 0;\">Seventh Sky does not guarantee a buyer's financial capacity, finance approval or completion of the purchase;</li><li style=\"margin:2px 0;\">the Client remains responsible for deciding whether to accept an offer; and</li><li style=\"margin:2px 0;\">lawyers, accountants, valuers, finance providers and other independent professionals remain responsible for their own advice and services.</li></ul><p style=\"margin:6px 0;\">Seventh Sky remains responsible for coordinating the Services requested by the Client with reasonable care and skill.</p>"],
  ["SERVICE COMPLETION", "<p style=\"margin:6px 0;\">The Services shall be considered completed when the agreed scope of work specified in the Quotation or Work Order has been substantially delivered.</p><p style=\"margin:6px 0;\">Depending on the selected services, completion may include:</p><ul style=\"margin:4px 0 8px 18px;padding:0;list-style-type:disc;\"><li style=\"margin:2px 0;\">business preparation completed;</li><li style=\"margin:2px 0;\">marketing activities completed;</li><li style=\"margin:2px 0;\">prospective buyers introduced;</li><li style=\"margin:2px 0;\">inspections coordinated;</li><li style=\"margin:2px 0;\">negotiations coordinated;</li><li style=\"margin:2px 0;\">due diligence coordinated;</li><li style=\"margin:2px 0;\">sale documentation coordinated;</li><li style=\"margin:2px 0;\">settlement completed;</li><li style=\"margin:2px 0;\">business handover coordinated; or</li><li style=\"margin:2px 0;\">ongoing business sale management services delivered for the agreed service period.</li></ul><p style=\"margin:6px 0;\">Where ongoing sale management services are engaged, completion shall occur at the expiry of the agreed service period unless renewed by mutual agreement.</p>"],
  ["CLIENT COMPLAINTS & SERVICE ISSUES", "<p style=\"margin:6px 0;\">If the Client believes that the Services have not been delivered in accordance with the agreed scope, the Client should notify Seventh Sky as soon as reasonably practicable.</p><p style=\"margin:6px 0;\">Upon receiving a complaint, Seventh Sky will:</p><ul style=\"margin:4px 0 8px 18px;padding:0;list-style-type:disc;\"><li style=\"margin:2px 0;\">acknowledge the complaint;</li><li style=\"margin:2px 0;\">investigate the matter;</li><li style=\"margin:2px 0;\">liaise with relevant parties where appropriate;</li><li style=\"margin:2px 0;\">take reasonable steps to resolve the issue; and</li><li style=\"margin:2px 0;\">keep the Client informed of the outcome.</li></ul><p style=\"margin:6px 0;\">Where the issue arises from Seventh Sky's administrative oversight, reasonable efforts will be made to rectify the matter promptly.</p><p style=\"margin:6px 0;\">Nothing in this Agreement limits any rights available to the Client under applicable law.</p>"],
  ["LIABILITY", "<p style=\"margin:6px 0;\">To the extent permitted by the laws of Bangladesh:</p><ul style=\"margin:4px 0 8px 18px;padding:0;list-style-type:disc;\"><li style=\"margin:2px 0;\">Seventh Sky will provide the Services with reasonable care and skill.</li><li style=\"margin:2px 0;\">Seventh Sky is responsible only for the Services it has agreed to provide under this Agreement.</li><li style=\"margin:2px 0;\">The Client remains responsible for the ownership, operation and legal compliance of the business.</li><li style=\"margin:2px 0;\">Prospective buyers remain responsible for the accuracy of the information they provide and for complying with any sale agreement entered into with the Client.</li></ul><p style=\"margin:6px 0;\">Independent professionals, including lawyers, accountants, valuers, financial advisers and tax advisers, remain responsible for their own advice and services.</p><p style=\"margin:6px 0;\">Neither Party shall be liable for delays or failures resulting from circumstances beyond their reasonable control.</p>"],
  ["LIMITATION OF LIABILITY", "<p style=\"margin:6px 0;\">Except where liability cannot legally be excluded or limited, Seventh Sky shall not be liable for:</p><ul style=\"margin:4px 0 8px 18px;padding:0;list-style-type:disc;\"><li style=\"margin:2px 0;\">a prospective buyer deciding not to proceed with the purchase;</li><li style=\"margin:2px 0;\">the Client deciding not to accept an offer;</li><li style=\"margin:2px 0;\">delays caused by finance approval, due diligence or regulatory requirements;</li><li style=\"margin:2px 0;\">changes in business value or market conditions;</li><li style=\"margin:2px 0;\">inaccurate or incomplete information provided by the Client, buyers or third parties;</li><li style=\"margin:2px 0;\">the actions or omissions of independent professionals;</li><li style=\"margin:2px 0;\">business interruption;</li><li style=\"margin:2px 0;\">loss of business opportunity, profit or goodwill; or</li><li style=\"margin:2px 0;\">events beyond Seventh Sky's reasonable control.</li></ul><p style=\"margin:6px 0;\">Where permitted by law, Seventh Sky's total liability arising from a project shall not exceed the amount paid by the Client for the affected Services.</p><p style=\"margin:6px 0;\">This clause does not exclude liability arising from fraud, wilful misconduct or any liability that cannot legally be excluded.</p>"],
  ["CONFIDENTIALITY & PRIVACY", "<p style=\"margin:6px 0;\">Each Party agrees to keep confidential all non-public information obtained through this Agreement.</p><p style=\"margin:6px 0;\">Business and personal information will only be collected, used and disclosed for:</p><ul style=\"margin:4px 0 8px 18px;padding:0;list-style-type:disc;\"><li style=\"margin:2px 0;\">providing the requested Services;</li><li style=\"margin:2px 0;\">marketing and promoting the business for sale;</li><li style=\"margin:2px 0;\">communicating with the Client, prospective buyers and authorised representatives;</li><li style=\"margin:2px 0;\">coordinating with lawyers, accountants, valuers, financial institutions and other authorised third parties;</li><li style=\"margin:2px 0;\">preparing quotations, Work Orders and invoices;</li><li style=\"margin:2px 0;\">complying with legal obligations; or</li><li style=\"margin:2px 0;\">other purposes authorised by the Client.</li></ul><p style=\"margin:6px 0;\">Neither Party shall disclose confidential information to any third party without prior consent unless required by law.</p><p style=\"margin:6px 0;\">These obligations continue after completion or termination of this Agreement.</p>"],
  ["FORCE MAJEURE", "<p style=\"margin:6px 0;\">Neither Party shall be responsible for delays or failure to perform caused by circumstances beyond its reasonable control, including:</p><ul style=\"margin:4px 0 8px 18px;padding:0;list-style-type:disc;\"><li style=\"margin:2px 0;\">natural disasters;</li><li style=\"margin:2px 0;\">severe weather;</li><li style=\"margin:2px 0;\">government restrictions;</li><li style=\"margin:2px 0;\">industrial action;</li><li style=\"margin:2px 0;\">civil unrest;</li><li style=\"margin:2px 0;\">pandemics;</li><li style=\"margin:2px 0;\">major technology failures;</li><li style=\"margin:2px 0;\">financial system disruptions; or</li><li style=\"margin:2px 0;\">other unforeseen events.</li></ul><p style=\"margin:6px 0;\">The affected Party shall notify the other Party as soon as reasonably practicable and resume performance once the event has ended.</p>"],
  ["CLIENT ACKNOWLEDGEMENTS", "<p style=\"margin:6px 0;\">The Client acknowledges that:</p><ul style=\"margin:4px 0 8px 18px;padding:0;list-style-type:disc;\"><li style=\"margin:2px 0;\">they have reviewed and accepted the Quotation or Work Order before the Services commence;</li><li style=\"margin:2px 0;\">the successful sale of the business depends on market conditions and suitable buyer availability;</li><li style=\"margin:2px 0;\">the final decision to sell the business remains with the Client;</li><li style=\"margin:2px 0;\">prospective buyers may withdraw or amend offers during negotiations or due diligence;</li><li style=\"margin:2px 0;\">independent legal, taxation, accounting and financial advice should be obtained before entering into a sale agreement;</li><li style=\"margin:2px 0;\">some Services involve coordination with independent third parties; and</li><li style=\"margin:2px 0;\">they have had the opportunity to ask questions and obtain independent professional advice before entering into this Agreement.</li></ul>"],
  ["SUSPENSION & TERMINATION", "<p style=\"margin:10px 0 4px;font-weight:700;color:#012a4e;\">21.1 Suspension</p><p style=\"margin:6px 0;\">Seventh Sky may suspend the Services where:</p><ul style=\"margin:4px 0 8px 18px;padding:0;list-style-type:disc;\"><li style=\"margin:2px 0;\">the Client fails to make payment in accordance with this Agreement;</li><li style=\"margin:2px 0;\">the Client fails to provide information or documents reasonably required to perform the Services;</li><li style=\"margin:2px 0;\">the Client provides false, misleading or fraudulent information;</li><li style=\"margin:2px 0;\">the Client requests suspension; or</li><li style=\"margin:2px 0;\">continuation of the Services would be unlawful or impracticable.</li></ul><p style=\"margin:6px 0;\">Where practicable, Seventh Sky will notify the Client before suspending the Services.</p><p style=\"margin:10px 0 4px;font-weight:700;color:#012a4e;\">21.2 Termination</p><p style=\"margin:6px 0;\">Either Party may terminate this Agreement by providing thirty (30) days' written notice, provided all completed Services and outstanding payments have been settled.</p><p style=\"margin:6px 0;\">Seventh Sky may terminate this Agreement immediately where the Client:</p><ul style=\"margin:4px 0 8px 18px;padding:0;list-style-type:disc;\"><li style=\"margin:2px 0;\">commits a material breach of this Agreement;</li><li style=\"margin:2px 0;\">provides false or fraudulent information;</li><li style=\"margin:2px 0;\">fails to make payment after receiving written notice;</li><li style=\"margin:2px 0;\">engages in unlawful conduct; or</li><li style=\"margin:2px 0;\">prevents Seventh Sky from performing the agreed Services.</li></ul><p style=\"margin:6px 0;\">Where the Client terminates after Services have commenced, the Client remains responsible for payment for:</p><ul style=\"margin:4px 0 8px 18px;padding:0;list-style-type:disc;\"><li style=\"margin:2px 0;\">Services already completed;</li><li style=\"margin:2px 0;\">marketing costs incurred;</li><li style=\"margin:2px 0;\">buyer sourcing activities completed;</li><li style=\"margin:2px 0;\">inspections coordinated;</li><li style=\"margin:2px 0;\">approved third-party costs incurred; and</li><li style=\"margin:2px 0;\">other reasonable expenses incurred before termination.</li></ul><p style=\"margin:6px 0;\">Termination does not affect any rights or obligations that arose before the termination date.</p>"],
  ["NON-CIRCUMVENTION", "<p style=\"margin:6px 0;\">The Client acknowledges that Seventh Sky invests significant time, expertise and commercial resources in marketing the business and introducing prospective buyers.</p><p style=\"margin:6px 0;\">Accordingly, where Seventh Sky introduces a prospective buyer, investor or authorised representative to the Client, the Client agrees that, during the term of this Agreement and for twelve (12) months after the introduction, the Client will not intentionally bypass Seventh Sky to complete a sale transaction with the introduced party without Seventh Sky's prior written consent.</p><p style=\"margin:6px 0;\">Where a sale is completed with a buyer introduced by Seventh Sky during this period, the agreed service fees or success fees specified in the approved Quotation or Work Order remain payable.</p><p style=\"margin:6px 0;\">This clause does not restrict the Client from selling the business to a purchaser who was not introduced by Seventh Sky.</p>"],
  ["GENERAL PROVISIONS", "<p style=\"margin:6px 0;\">Unless otherwise agreed in writing:</p><ul style=\"margin:4px 0 8px 18px;padding:0;list-style-type:disc;\"><li style=\"margin:2px 0;\">this Agreement, together with the accepted Quotation, Work Order and Schedules, constitutes the entire agreement between the Parties;</li><li style=\"margin:2px 0;\">any amendment must be made in writing and signed or electronically accepted by both Parties;</li><li style=\"margin:2px 0;\">failure by either Party to enforce any provision does not waive its rights;</li><li style=\"margin:2px 0;\">if any provision is found to be invalid or unenforceable, the remaining provisions shall continue in full force and effect; and</li><li style=\"margin:2px 0;\">notices under this Agreement may be delivered by hand, courier, registered post or email.</li></ul>"],
  ["GOVERNING LAW & DISPUTE RESOLUTION", "<p style=\"margin:6px 0;\">This Agreement shall be governed by the laws of the People's Republic of Bangladesh.</p><p style=\"margin:6px 0;\">The Parties agree to make reasonable efforts to resolve any dispute through good faith discussions before commencing legal proceedings.</p><p style=\"margin:6px 0;\">If the dispute cannot be resolved through negotiation, the Parties may agree to mediation or another recognised alternative dispute resolution process before referring the matter to the competent courts of Bangladesh.</p><p style=\"margin:6px 0;\">Nothing in this clause prevents either Party from seeking urgent legal or equitable relief where necessary.</p>"],
  ["EXECUTION", "<p style=\"margin:6px 0;\">By signing this Agreement, the Parties confirm that they:</p><ul style=\"margin:4px 0 8px 18px;padding:0;list-style-type:disc;\"><li style=\"margin:2px 0;\">have read and understood this Agreement;</li><li style=\"margin:2px 0;\">have had the opportunity to obtain independent legal, financial, taxation or professional advice;</li><li style=\"margin:2px 0;\">enter into this Agreement voluntarily; and</li><li style=\"margin:2px 0;\">agree to be legally bound by its terms.</li></ul><p style=\"margin:6px 0;\">This Agreement may be executed in counterparts and by electronic signature, including through approved electronic signature platforms such as DocuSign. Each signed copy shall be deemed an original and together constitute one Agreement.</p>"],
];
